//! exFAT 1.00 data volumes generated by scripts/exfat_image.py.
use crate::storage::{self, File};
use alloc::vec::Vec;

pub const LENGTH: u32 = 65536;
pub const DRAFT: &str = "KOSDRAFT.KDR";
const HEAP: u32 = 256;
const CLUSTERS: u32 = (LENGTH - HEAP) / 8;
const ROOT_CLUSTER: u32 = 37;
const ROOT_LEN: usize = 16384;
const CLUSTER: usize = 4096;
const BITMAP: usize = CLUSTERS.div_ceil(8) as usize;

#[derive(Clone)]
struct Entry {
    name: crate::text::Text<32>,
    offset: usize,
    count: usize,
    cluster: u32,
    len: usize,
    managed: bool,
}

pub struct Volume {
    start: u32,
    root: alloc::boxed::Box<[u8]>,
    bitmap: [u8; 1024],
    healthy: bool,
}

fn word(b: &[u8], index: usize) -> u16 {
    u16::from_le_bytes(b[index..index + 2].try_into().unwrap())
}
fn dword(b: &[u8], index: usize) -> u32 {
    u32::from_le_bytes(b[index..index + 4].try_into().unwrap())
}
fn qword(b: &[u8], index: usize) -> u64 {
    u64::from_le_bytes(b[index..index + 8].try_into().unwrap())
}
fn sum(data: &[u8], skip: &[usize]) -> u16 {
    data.iter()
        .enumerate()
        .filter(|(i, _)| !skip.contains(i))
        .fold(0u16, |sum, (_, &b)| {
            sum.rotate_right(1).wrapping_add(u16::from(b))
        })
}
fn hash(name: &str) -> u16 {
    name.bytes()
        .flat_map(|byte| [byte.to_ascii_uppercase(), 0])
        .fold(0u16, |sum, b| {
            sum.rotate_right(1).wrapping_add(u16::from(b))
        })
}

pub fn valid_name(name: &str) -> bool {
    !name.is_empty()
        && name.len() <= 32
        && !name.ends_with(['.', ' '])
        && name
            .bytes()
            .all(|b| (32..127).contains(&b) && !b"\"*/:<>?\\|".contains(&b))
}

impl Volume {
    pub fn mount(start: u32) -> Option<Self> {
        let mut boot = [0; 12 * 512];
        for lba in [start, start + 12] {
            if !storage::blocks(lba, &mut boot, false)
                || &boot[3..11] != b"EXFAT   "
                || boot[11..64].iter().any(|&b| b != 0)
                || qword(&boot, 64) != u64::from(start)
                || qword(&boot, 72) != u64::from(LENGTH)
                || dword(&boot, 80) != 128
                || dword(&boot, 84) != 64
                || dword(&boot, 88) != HEAP
                || dword(&boot, 92) != CLUSTERS
                || dword(&boot, 96) != ROOT_CLUSTER
                || word(&boot, 104) != 0x100
                || word(&boot, 106) & 7 != 0
                || boot[108..111] != [9, 3, 1]
                || boot[510..512] != [0x55, 0xaa]
            {
                return None;
            }
            let checksum = boot[..11 * 512]
                .iter()
                .enumerate()
                .filter(|(i, _)| ![106, 107, 112].contains(i))
                .fold(0u32, |sum, (_, &b)| {
                    sum.rotate_right(1).wrapping_add(u32::from(b))
                });
            if !boot[11 * 512..]
                .chunks_exact(4)
                .all(|b| b == checksum.to_le_bytes())
            {
                return None;
            }
        }
        let mut v = Self {
            start,
            root: alloc::vec![0; ROOT_LEN].into_boxed_slice(),
            bitmap: [0; 1024],
            healthy: true,
        };
        let root_lba = v.lba(ROOT_CLUSTER);
        let mut fat = [0; 512];
        if !storage::blocks(start + 128, &mut fat, false)
            || (ROOT_CLUSTER..ROOT_CLUSTER + 3).any(|id| dword(&fat, id as usize * 4) != id + 1)
            || dword(&fat, (ROOT_CLUSTER + 3) as usize * 4) < 0xfffffff8
            || !storage::blocks(root_lba, &mut v.root, false)
            || v.root[32] != 0x81
            || dword(&v.root, 52) != 2
            || qword(&v.root, 56) != BITMAP as u64
            || v.root[64] != 0x82
            || dword(&v.root, 84) != 3
            || !storage::blocks(start + HEAP, &mut v.bitmap, false)
            || !(2..35)
                .chain(ROOT_CLUSTER..ROOT_CLUSTER + 4)
                .all(|id| v.allocated(id))
        {
            return None;
        }
        v.entries()?;
        Some(v)
    }
    fn lba(&self, id: u32) -> u32 {
        self.start + HEAP + 8 * (id - 2)
    }
    fn allocated(&self, id: u32) -> bool {
        let i = (id - 2) as usize;
        self.bitmap[i / 8] & (1 << (i % 8)) != 0
    }
    fn file_cluster(id: u32) -> bool {
        (35..CLUSTERS + 2).contains(&id) && !(ROOT_CLUSTER..ROOT_CLUSTER + 4).contains(&id)
    }
    fn single_cluster(&self, cluster: u32, no_chain: bool) -> bool {
        if !Self::file_cluster(cluster) || !self.allocated(cluster) {
            return false;
        }
        if no_chain {
            return true;
        }
        let mut fat = [0; 512];
        let index = cluster as usize * 4;
        storage::blocks(self.start + 128 + (index / 512) as u32, &mut fat, false)
            && dword(&fat, index % 512) >= 0xfffffff8
    }
    fn set_allocation(&mut self, id: u32, state: bool) -> bool {
        let i = (id - 2) as usize;
        if state {
            self.bitmap[i / 8] |= 1 << (i % 8);
        } else {
            self.bitmap[i / 8] &= !(1 << (i % 8));
        }
        let sector = i / (8 * 512);
        storage::blocks(
            self.start + HEAP + sector as u32,
            &mut self.bitmap[sector * 512..(sector + 1) * 512],
            true,
        )
    }
    fn entries(&self) -> Option<Vec<Entry>> {
        let mut out: Vec<Entry> = Vec::new();
        let mut offset = 96;
        while offset < ROOT_LEN {
            let entry = &self.root[offset..offset + 32];
            if entry[0] == 0 {
                break;
            }
            if entry[0] < 128 {
                offset += 32;
                continue;
            }
            if entry[0] != 0x85 {
                if entry[0] & 0x60 == 0x20 {
                    offset += 32;
                    continue;
                }
                return None;
            }
            let count = usize::from(entry[1]) + 1;
            let end = offset + count * 32;
            let set = self.root.get(offset..end)?;
            if !(3..=19).contains(&count) || sum(set, &[2, 3]) != word(set, 2) || set[32] != 0xc0 {
                return None;
            }
            let len = usize::from(set[35]);
            let size = qword(set, 56);
            let cluster = dword(set, 52);
            if len == 0 || len.div_ceil(15) + 2 != count {
                return None;
            }
            let mut name = crate::text::Text::new();
            let mut scanned = 0;
            let mut ascii = len <= 32;
            for row in set[64..].chunks_exact(32) {
                if row[0] != 0xc1 {
                    return None;
                }
                for value in row[2..].chunks_exact(2).take(len - scanned) {
                    scanned += 1;
                    if value[1] != 0 || !(32..127).contains(&value[0]) {
                        ascii = false;
                    }
                    name.push(value[0]);
                }
            }
            if !ascii {
                offset = end;
                continue;
            }
            if !valid_name(name.str())
                || word(set, 36) != hash(name.str())
                || out.iter().any(|old| {
                    old.name.str().eq_ignore_ascii_case(name.str())
                        || (cluster != 0 && old.cluster == cluster)
                })
            {
                return None;
            }
            out.push(Entry {
                name,
                offset,
                count,
                cluster,
                len: (size.min(CLUSTER as u64)) as usize,
                managed: word(entry, 4) & 0x11 == 0
                    && size
                        <= if name.str().eq_ignore_ascii_case(DRAFT) {
                            CLUSTER as u64
                        } else {
                            storage::CAP as u64
                        }
                    && qword(set, 40) == size
                    && ((size == 0 && cluster == 0)
                        || (size != 0
                            && set[33] & 1 != 0
                            && self.single_cluster(cluster, set[33] & 2 != 0))),
            });
            offset = end;
        }
        Some(out)
    }
    fn read_entry(&self, entry: &Entry, data: &mut [u8]) -> bool {
        if entry.len == 0 {
            return true;
        }
        let mut block = [0; CLUSTER];
        storage::blocks(self.lba(entry.cluster), &mut block, false) && {
            data[..entry.len].copy_from_slice(&block[..entry.len]);
            true
        }
    }
    pub fn load(&self, files: &mut [File]) -> bool {
        let Some(entries) = self.entries() else {
            return false;
        };
        for (i, entry) in entries
            .iter()
            .filter(|entry| entry.managed && !entry.name.str().eq_ignore_ascii_case(DRAFT))
            .enumerate()
        {
            let Some(file) = files.get_mut(i) else {
                return false;
            };
            if entry.len > file.data.bytes.len() || !self.read_entry(entry, &mut file.data.bytes) {
                return false;
            }
            file.used = true;
            file.name = entry.name;
            file.data.len = entry.len;
        }
        true
    }
    pub fn read_draft(&self, data: &mut [u8]) -> bool {
        self.entries()
            .and_then(|entries| {
                entries
                    .into_iter()
                    .find(|entry| entry.name.str().eq_ignore_ascii_case(DRAFT))
            })
            .is_some_and(|entry| {
                entry.managed && entry.len == data.len() && self.read_entry(&entry, data)
            })
    }
    fn dirty(&self, dirty: bool) -> bool {
        let mut boot = [0; 512];
        for lba in [self.start, self.start + 12] {
            if !storage::blocks(lba, &mut boot, false) {
                return false;
            }
            boot[106] = (boot[106] & !2) | (u8::from(dirty) << 1);
            if !storage::blocks(lba, &mut boot, true) {
                return false;
            }
        }
        true
    }
    fn update(&mut self, name: &str, data: Option<&[u8]>) -> bool {
        if !self.healthy || !valid_name(name) {
            return false;
        }
        let Some(entries) = self.entries() else {
            return false;
        };
        let old = entries
            .iter()
            .find(|entry| entry.name.str().eq_ignore_ascii_case(name));
        if old.is_some_and(|entry| !entry.managed) {
            return false;
        }
        if let Some((entry, value)) = old.zip(data) {
            let mut prior = [0; CLUSTER];
            if entry.len == value.len()
                && self.read_entry(entry, &mut prior)
                && &prior[..entry.len] == value
                && entry.name.str() == name
            {
                return true;
            }
        }
        let mut target = None;
        let mut cluster = 0;
        let count = 2 + name.len().div_ceil(15);
        if let Some(value) = data {
            if value.len() > CLUSTER {
                return false;
            }
            if !value.is_empty() {
                let Some(free) =
                    (35..CLUSTERS + 2).find(|&id| Self::file_cluster(id) && !self.allocated(id))
                else {
                    return false;
                };
                cluster = free;
            }
            if let Some(entry) = old.filter(|entry| entry.count == count) {
                target = Some(entry.offset);
            } else {
                target = (96..=ROOT_LEN - count * 32).step_by(32).find(|&p| {
                    self.root[p..p + count * 32]
                        .chunks_exact(32)
                        .all(|r| r[0] < 128)
                });
            }
            if target.is_none() {
                return false;
            }
        } else if old.is_none() {
            return true;
        }

        self.healthy = false;
        if !self.dirty(true) {
            return false;
        }
        if let Some(entry) = old {
            for i in 0..entry.count {
                self.root[entry.offset + i * 32] &= 0x7f;
            }
        }
        if let Some((offset, value)) = target.zip(data) {
            if cluster != 0 {
                let mut buffer = [0u8; CLUSTER];
                buffer[..value.len()].copy_from_slice(value);
                if !storage::blocks(self.lba(cluster), &mut buffer, true)
                    || !self.set_allocation(cluster, true)
                {
                    return false;
                }
            }
            let set = &mut self.root[offset..offset + count * 32];
            set.fill(0);
            set[0] = 0x85;
            set[1] = count as u8 - 1;
            set[4] = if name.eq_ignore_ascii_case(DRAFT) {
                2
            } else {
                0x20
            };
            // exFAT timestamps initialize to 1980-01-01.
            for field in [8, 12, 16] {
                set[field + 2] = 0x21;
            }
            set[32..36].copy_from_slice(&[
                0xc0,
                if cluster == 0 { 1 } else { 3 },
                0,
                name.len() as u8,
            ]);
            set[36..38].copy_from_slice(&hash(name).to_le_bytes());
            set[40..48].copy_from_slice(&(value.len() as u64).to_le_bytes());
            set[52..56].copy_from_slice(&cluster.to_le_bytes());
            set[56..64].copy_from_slice(&(value.len() as u64).to_le_bytes());
            for (row, bytes) in set[64..]
                .chunks_exact_mut(32)
                .zip(name.as_bytes().chunks(15))
            {
                row[0] = 0xc1;
                for (i, &byte) in bytes.iter().enumerate() {
                    row[2 + i * 2] = byte;
                }
            }
            let checksum = sum(set, &[2, 3]);
            set[2..4].copy_from_slice(&checksum.to_le_bytes());
        }
        let lba = self.lba(ROOT_CLUSTER);
        if !storage::blocks(lba, &mut self.root, true) {
            return false;
        }
        if let Some(entry) = old.filter(|entry| entry.cluster != 0) {
            if !self.set_allocation(entry.cluster, false) {
                return false;
            }
        }
        self.healthy = self.dirty(false);
        self.healthy
    }
    pub fn save(&mut self, files: &[File]) -> bool {
        let Some(entries) = self.entries() else {
            return false;
        };
        for old in entries {
            if old.managed
                && !old.name.str().eq_ignore_ascii_case(DRAFT)
                && !files
                    .iter()
                    .any(|file| file.used && file.name.str().eq_ignore_ascii_case(old.name.str()))
                && !self.update(old.name.str(), None)
            {
                return false;
            }
        }
        files
            .iter()
            .filter(|file| file.used)
            .all(|file| self.update(file.name.str(), Some(&file.data.bytes[..file.data.len])))
    }
    pub fn save_draft(&mut self, data: &[u8]) -> bool {
        self.update(DRAFT, Some(data))
    }
}
